void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.y * 2.2;

    mat3 r = mat3(
        0,-3.*sin(iTime/7.),2.*sin(iTime/4.2 + 2.)-1.,
        0, 0,-1.5*cos(iTime/3.)+1.,
        0,0,0
    )*0.1;
    r -= transpose(r);
    mat3 id = mat3(
        1,0,0,
        0,1,0,
        0,0,1
    );
    mat3 R =
        id + r * (
        id + r/2. * (
        id + r/3. * (
        id + r/4. * (
        id + r/5. * (
        id + r/6. * (
        id + r/7. * (
        id + r/8. * (
        id + r/9. * (
        id + r/10. * (
        id + r/11. * (
        id + r/12.
    )))))))))));

    mat3 Q = outerProduct(R[0],R[0])/3.5 - outerProduct(R[1],R[1])/5.0;
    float a,b,c;
    a = Q[2][2];
    b = 2.*dot(Q[2].xy, uv) - R[2][2];
    c = dot(vec3(uv,0), Q*vec3(uv,0) - vec3(R[2].xy,0));
    float Delta = b*b - 4.*a*c;
    vec3 pos1 = R*vec3(uv, (-b+sqrt(max(0.,Delta)))/(2.*a));
    vec3 pos2 = R*vec3(uv, (-b-sqrt(max(0.,Delta)))/(2.*a));

    // Time varying pixel color
    vec3 col = Delta >= 0. ? vec3(0.1,
        (length(pos1) < 1. ? max(pos1.x,0.1) : 0.) +
        (length(pos2) < 1. ? max(pos2.x,0.1) : 0.),
        (length(uv) < 1. ? 0.2 : 0.)) : vec3(0);

    // Output to screen
    fragColor = vec4(col,1.0);
}
